import { sql } from "drizzle-orm"
import {
  bigint,
  boolean,
  check,
  foreignKey,
  index,
  integer,
  jsonb,
  pgSequence,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core"

/**
 * Postgres schema. Kept free of app imports so drizzle-kit can load it on its own.
 * IDs are prefixed strings (`prd_`, `txn_`...) generated by the app.
 * Money is stored in minor units as bigint.
 */

const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" })
const createdAt = () => ts("created_at").notNull().defaultNow()

/**
 * The company a row belongs to. Every write must say which one: there is deliberately no default, so a
 * forgotten workspace fails loudly instead of landing in some other company.
 */
const workspaceId = () =>
  text("workspace_id")
    .notNull()
    .references(() => workspaces.id, { onDelete: "cascade" })

export interface TimelineStepJson {
  kind: string
  at: string
  title: string
  detail?: string
  ok: boolean
}

/**
 * A company using this install. Self-hosted Community installs have exactly one; Cloud and Enterprise
 * can have many. Company-level settings live here; install-level ones stay in `settings`.
 */
export const workspaces = pgTable(
  "workspaces",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    status: text("status").notNull().default("active"),
    /** Cloud: the slug of its billing plan. Self-hosted installs leave it as "community". */
    plan: text("plan").notNull().default("community"),
    defaultCurrency: text("default_currency").notNull().default("NGN"),
    /** Encrypted incoming-webhook URL for alerts. */
    alertsWebhookUrlEnc: text("alerts_webhook_url_enc"),
    /** Cloud billing: invoices are in NGN or USD. */
    billingCurrency: text("billing_currency").notNull().default("NGN"),
    /** Live use before this is free (the trial). Set by the first live payment. */
    trialEndsAt: ts("trial_ends_at"),
    /** Free months the super admin granted: live use before this is free too. */
    freeUntil: ts("free_until"),
    /** Days of trial still to start: set at sign-up, turned into trial_ends_at by the first live payment. */
    pendingTrialDays: integer("pending_trial_days"),
    /**
     * `ok`, or `past_due` once an invoice is unpaid after its due date: paid features pause and products
     * that haven't taken a live payment this month can't start. Payments already flowing carry on.
     */
    billingStatus: text("billing_status").notNull().default("ok"),
    pastDueSince: ts("past_due_since"),
    suspendedAt: ts("suspended_at"),
    suspendedReason: text("suspended_reason"),
    createdAt: createdAt(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [uniqueIndex("workspaces_slug_key").on(sql`lower(${t.slug})`)],
)

/** Single row (id = 1): install-wide settings. Company name, currency and alerts moved to `workspaces`. */
export const settings = pgTable("settings", {
  id: smallint("id").primaryKey().default(1),
  platformName: text("platform_name").notNull().default("YaroPay"),
  companyName: text("company_name").notNull().default("My company"),
  baseUrl: text("base_url").notNull(),
  defaultCurrency: text("default_currency").notNull().default("NGN"),
  /** Encrypted incoming-webhook URL for alerts. */
  alertsWebhookUrlEnc: text("alerts_webhook_url_enc"),
  /** Cloud: whether anyone can create a company from the sign-up page. The super admin opens it. */
  signupsOpen: boolean("signups_open").notNull().default(false),
  /** Cloud: the plan (slug) a company created from the sign-up page starts on. */
  signupPlan: text("signup_plan").notNull().default("standard"),
  /**
   * Operator settings saved from the platform console (OperatorSettingsService). Each one, when set,
   * wins over its env variable; null means "use the env value". Secrets are encrypted.
   */
  billingPaystackSecretKeyEnc: text("billing_paystack_secret_key_enc"),
  smtpUrlEnc: text("smtp_url_enc"),
  mailFrom: text("mail_from"),
  v1RateLimitPerMinute: integer("v1_rate_limit_per_minute"),
  gatewayTimeoutMs: integer("gateway_timeout_ms"),
  webhookTimeoutMs: integer("webhook_timeout_ms"),
  sessionDays: integer("session_days"),
  /** "standard" or "fast" (production always uses standard). */
  passwordHashCost: text("password_hash_cost"),
  /** "error", "warn", "log", "debug" or "verbose". */
  logLevel: text("log_level"),
  workerIntervalMs: integer("worker_interval_ms"),
  /** Changes whenever an operator setting does, so every API instance knows to reload them. */
  operatorUpdatedAt: ts("operator_updated_at"),
  /**
   * Gateways the install's operator has turned off: companies can't add new accounts on them. Accounts
   * already connected keep working and keep taking payments.
   */
  disabledGateways: text("disabled_gateways").array().notNull().default(sql`'{}'::text[]`),
  updatedAt: ts("updated_at").notNull().defaultNow(),
})

export const users = pgTable(
  "users",
  {
    id: text("id").primaryKey(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    disabledAt: ts("disabled_at"),
    lastActiveAt: ts("last_active_at"),
    /** Set when the member hides the setup guide on the dashboard. */
    onboardingDismissedAt: ts("onboarding_dismissed_at"),
    /** Two-step sign-in: the authenticator secret (encrypted), set once the first code is confirmed. */
    totpSecretEnc: text("totp_secret_enc"),
    /** A secret being set up but not yet confirmed with a code. */
    totpPendingSecretEnc: text("totp_pending_secret_enc"),
    totpEnabledAt: ts("totp_enabled_at"),
    /** The last time step a code was accepted for: older and equal steps are refused (no replays). */
    totpLastStep: bigint("totp_last_step", { mode: "number" }),
    /** sha256 of each unused recovery code. */
    recoveryCodeHashes: text("recovery_code_hashes").array().notNull().default(sql`'{}'::text[]`),
    /** `super_admin` runs YaroPay Cloud: the platform console. Granted only from the server's CLI. */
    platformRole: text("platform_role"),
    /**
     * When the address was confirmed. Every account starts confirmed (invited people got the link by email,
     * the owner set the install up) except Cloud sign-ups, which store null until the emailed link is used.
     */
    emailVerifiedAt: ts("email_verified_at").defaultNow(),
    createdAt: createdAt(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [uniqueIndex("users_email_key").on(sql`lower(${t.email})`)],
)

/** A person's place in a company: their role and product scope there. */
export const workspaceMembers = pgTable(
  "workspace_members",
  {
    workspaceId: text("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    role: text("role").notNull(),
    /** Null = every product in the workspace. */
    productIds: text("product_ids").array(),
    disabledAt: ts("disabled_at"),
    lastActiveAt: ts("last_active_at"),
    /** Set when the member hides the setup guide on the dashboard. */
    onboardingDismissedAt: ts("onboarding_dismissed_at"),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.workspaceId, t.userId] }), index("workspace_members_user_idx").on(t.userId)],
)

export const sessions = pgTable(
  "sessions",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    userAgent: text("user_agent"),
    ip: text("ip"),
    createdAt: createdAt(),
    lastSeenAt: ts("last_seen_at").notNull().defaultNow(),
    expiresAt: ts("expires_at").notNull(),
    revokedAt: ts("revoked_at"),
    /** The company this session is working in (members of several switch between them). */
    workspaceId: text("workspace_id").references(() => workspaces.id, { onDelete: "set null" }),
    /**
     * How the person proved who they are: `pending` (password right, authenticator code still owed;
     * only the code step is reachable), `password`, or `mfa` (password and code).
     */
    assurance: text("assurance").notNull().default("password"),
    /** When the password (and code) were last entered: sensitive actions need it to be recent. */
    authenticatedAt: ts("authenticated_at").notNull().defaultNow(),
    /** Wrong codes entered on this pending session; too many ends it. */
    mfaFailures: integer("mfa_failures").notNull().default(0),
    /**
     * Cloud support view: a super admin's session looking at another company, read-only, until
     * support_expires_at. Every change is refused while it lasts.
     */
    supportWorkspaceId: text("support_workspace_id").references(() => workspaces.id, { onDelete: "set null" }),
    supportReason: text("support_reason"),
    supportExpiresAt: ts("support_expires_at"),
  },
  (t) => [uniqueIndex("sessions_token_hash_key").on(t.tokenHash), index("sessions_user_idx").on(t.userId)],
)

export const invites = pgTable(
  "invites",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    email: text("email").notNull(),
    role: text("role").notNull(),
    productIds: text("product_ids").array(),
    tokenHash: text("token_hash").notNull(),
    invitedById: text("invited_by_id").references(() => users.id, { onDelete: "set null" }),
    invitedByName: text("invited_by_name").notNull(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    acceptedAt: ts("accepted_at"),
    revokedAt: ts("revoked_at"),
  },
  (t) => [uniqueIndex("invites_token_hash_key").on(t.tokenHash)],
)

/** Links that confirm a sign-up's email address. Single use, 24 hours. */
export const emailVerifications = pgTable(
  "email_verifications",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    usedAt: ts("used_at"),
  },
  (t) => [uniqueIndex("email_verifications_token_hash_key").on(t.tokenHash)],
)

export const passwordResets = pgTable(
  "password_resets",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    usedAt: ts("used_at"),
  },
  (t) => [uniqueIndex("password_resets_token_hash_key").on(t.tokenHash)],
)

/**
 * Browsers someone chose to trust after entering their authenticator code: signing in again from one
 * still needs the password, but not the code, until expires_at (fixed 30 days from creation). The cookie
 * holds a random token; only its SHA-256 is stored. Changing or resetting the password, turning two-step
 * sign-in off or resetting it, and disabling the account delete every row for that person.
 */
export const trustedBrowsers = pgTable(
  "trusted_browsers",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    /** "Chrome on macOS": what the person sees in Settings → Security. */
    label: text("label").notNull(),
    createdAt: createdAt(),
    lastUsedAt: ts("last_used_at"),
    expiresAt: ts("expires_at").notNull(),
  },
  (t) => [uniqueIndex("trusted_browsers_token_hash_key").on(t.tokenHash), index("trusted_browsers_user_idx").on(t.userId)],
)

export const connections = pgTable(
  "connections",
  {
  id: text("id").primaryKey(),
  workspaceId: workspaceId(),
  gatewayId: text("gateway_id").notNull(),
  label: text("label").notNull(),
  mode: text("mode").notNull(),
  /** AES-256-GCM encrypted JSON of every credential field. */
  credentialsEnc: text("credentials_enc").notNull(),
  /** Display copy with secret fields masked. */
  credentialsMasked: jsonb("credentials_masked").$type<Record<string, string>>().notNull(),
  status: text("status").notNull().default("active"),
  lastError: text("last_error"),
  /** Part of the sample data set (fake keys); removed together from Settings. */
  sample: boolean("sample").notNull().default(false),
  createdAt: createdAt(),
  lastEventAt: ts("last_event_at"),
  },
  (t) => [uniqueIndex("connections_workspace_id_key").on(t.workspaceId, t.id)],
)

export const products = pgTable(
  "products",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    kind: text("kind").notNull(),
    websiteUrl: text("website_url").notNull(),
    colorSlot: smallint("color_slot").notNull(),
    referencePrefix: text("reference_prefix").notNull(),
    webhookUrl: text("webhook_url").notNull(),
    successUrl: text("success_url").notNull(),
    failureUrl: text("failure_url").notNull(),
    cancelUrl: text("cancel_url"),
    liveKeyHash: text("live_key_hash").notNull(),
    liveKeyPreview: text("live_key_preview").notNull(),
    testKeyHash: text("test_key_hash").notNull(),
    testKeyPreview: text("test_key_preview").notNull(),
    signingSecretEnc: text("signing_secret_enc").notNull(),
    signingSecretPreview: text("signing_secret_preview").notNull(),
    status: text("status").notNull().default("active"),
    /** Part of the sample data set: never sent real deliveries in the background. */
    sample: boolean("sample").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("products_workspace_id_key").on(t.workspaceId, t.id),
    uniqueIndex("products_prefix_key").on(t.workspaceId, t.referencePrefix),
    uniqueIndex("products_slug_key").on(t.workspaceId, t.slug),
    uniqueIndex("products_live_key_key").on(t.liveKeyHash),
    uniqueIndex("products_test_key_key").on(t.testKeyHash),
    check("products_color_slot_range", sql`${t.colorSlot} between 1 and 8`),
  ],
)

export const productGateways = pgTable(
  "product_gateways",
  {
    workspaceId: workspaceId(),
    productId: text("product_id").notNull(),
    connectionId: text("connection_id").notNull(),
    isDefault: boolean("is_default").notNull().default(false),
    position: integer("position").notNull().default(0),
  },
  (t) => [
    primaryKey({ columns: [t.productId, t.connectionId] }),
    // The database refuses to attach one company's product to another company's gateway account.
    foreignKey({ name: "product_gateways_product_fk", columns: [t.workspaceId, t.productId], foreignColumns: [products.workspaceId, products.id] }).onDelete("cascade"),
    foreignKey({ name: "product_gateways_connection_fk", columns: [t.workspaceId, t.connectionId], foreignColumns: [connections.workspaceId, connections.id] }).onDelete("cascade"),
  ],
)

export const transactions = pgTable(
  "transactions",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    reference: text("reference").notNull(),
    productId: text("product_id").notNull(),
    connectionId: text("connection_id").notNull(),
    gatewayId: text("gateway_id").notNull(),
    mode: text("mode").notNull(),
    amount: bigint("amount", { mode: "number" }).notNull(),
    fee: bigint("fee", { mode: "number" }).notNull().default(0),
    currency: text("currency").notNull(),
    status: text("status").notNull(),
    channel: text("channel"),
    customerEmail: text("customer_email").notNull(),
    customerName: text("customer_name").notNull().default(""),
    metadata: jsonb("metadata").$type<Record<string, unknown>>().notNull().default({}),
    gatewayTransactionId: text("gateway_transaction_id"),
    /** The gateway's id for the checkout YaroPay created (Stripe session, PayPal order), when it gave one. */
    checkoutId: text("checkout_id"),
    authorizationUrl: text("authorization_url"),
    idempotencyKey: text("idempotency_key"),
    timeline: jsonb("timeline").$type<TimelineStepJson[]>().notNull().default([]),
    createdAt: createdAt(),
    paidAt: ts("paid_at"),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    foreignKey({ name: "transactions_product_fk", columns: [t.workspaceId, t.productId], foreignColumns: [products.workspaceId, products.id] }).onDelete("cascade"),
    uniqueIndex("transactions_workspace_id_key").on(t.workspaceId, t.id),
    uniqueIndex("transactions_reference_key").on(t.workspaceId, t.reference),
    uniqueIndex("transactions_idempotency_key").on(t.productId, t.idempotencyKey),
    index("transactions_mode_created_idx").on(t.mode, t.createdAt),
    index("transactions_product_created_idx").on(t.productId, t.createdAt),
  ],
)

export const webhookEvents = pgTable(
  "webhook_events",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    gatewayId: text("gateway_id").notNull(),
    connectionId: text("connection_id").notNull(),
    mode: text("mode").notNull(),
    type: text("type").notNull(),
    reference: text("reference"),
    signatureValid: boolean("signature_valid").notNull(),
    /** Null = unrouted. */
    productId: text("product_id").references(() => products.id, { onDelete: "set null" }),
    matchedBy: text("matched_by"),
    /** sha256 of the raw body: gateway retries of the same event are stored once. */
    dedupeKey: text("dedupe_key").notNull(),
    payload: jsonb("payload").$type<Record<string, unknown>>().notNull(),
    receivedAt: ts("received_at").notNull().defaultNow(),
    processedAt: ts("processed_at"),
    error: text("error"),
  },
  (t) => [
    uniqueIndex("webhook_events_dedupe_key").on(t.connectionId, t.dedupeKey),
    index("webhook_events_mode_received_idx").on(t.mode, t.receivedAt),
    index("webhook_events_reference_idx").on(t.workspaceId, t.reference),
  ],
)

export const webhookDeliveries = pgTable(
  "webhook_deliveries",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    eventId: text("event_id").references(() => webhookEvents.id, { onDelete: "set null" }),
    transactionId: text("transaction_id").references(() => transactions.id, { onDelete: "cascade" }),
    productId: text("product_id").notNull(),
    mode: text("mode").notNull(),
    url: text("url").notNull(),
    eventType: text("event_type").notNull(),
    payload: jsonb("payload").$type<Record<string, unknown>>().notNull(),
    state: text("state").notNull(),
    statusCode: integer("status_code"),
    attempts: integer("attempts").notNull().default(0),
    nextRetryAt: ts("next_retry_at"),
    lockedUntil: ts("locked_until"),
    latencyMs: integer("latency_ms"),
    responseSnippet: text("response_snippet").notNull().default(""),
    createdAt: createdAt(),
    lastAttemptAt: ts("last_attempt_at"),
  },
  (t) => [
    foreignKey({ name: "webhook_deliveries_product_fk", columns: [t.workspaceId, t.productId], foreignColumns: [products.workspaceId, products.id] }).onDelete("cascade"),
    index("webhook_deliveries_due_idx").on(t.state, t.nextRetryAt),
    index("webhook_deliveries_mode_created_idx").on(t.mode, t.createdAt),
    index("webhook_deliveries_transaction_idx").on(t.transactionId),
  ],
)

export const auditLog = pgTable(
  "audit_log",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    actorId: text("actor_id"),
    actorName: text("actor_name").notNull(),
    action: text("action").notNull(),
    target: text("target").notNull(),
    ip: text("ip"),
    sample: boolean("sample").notNull().default(false),
    at: ts("at").notNull().defaultNow(),
  },
  (t) => [index("audit_log_at_idx").on(t.workspaceId, t.at)],
)

export const notifications = pgTable(
  "notifications",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: text("type").notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    link: text("link"),
    severity: text("severity").notNull(),
    productId: text("product_id"),
    readAt: ts("read_at"),
    createdAt: createdAt(),
  },
  (t) => [index("notifications_user_created_idx").on(t.userId, t.workspaceId, t.createdAt)],
)

export const notificationPreferences = pgTable(
  "notification_preferences",
  {
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: text("type").notNull(),
    inApp: boolean("in_app").notNull(),
    email: boolean("email").notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.type] })],
)

/** Outbox for side effects that must survive restarts (emails, alert posts). */
export const jobs = pgTable(
  "jobs",
  {
    id: text("id").primaryKey(),
    kind: text("kind").notNull(),
    payload: jsonb("payload").$type<Record<string, unknown>>().notNull(),
    runAt: ts("run_at").notNull().defaultNow(),
    attempts: integer("attempts").notNull().default(0),
    maxAttempts: integer("max_attempts").notNull().default(5),
    lockedUntil: ts("locked_until"),
    lastError: text("last_error"),
    doneAt: ts("done_at"),
    createdAt: createdAt(),
  },
  (t) => [index("jobs_due_idx").on(t.doneAt, t.runAt)],
)

export type WorkspaceRow = typeof workspaces.$inferSelect
export type WorkspaceMemberRow = typeof workspaceMembers.$inferSelect
export type SettingsRow = typeof settings.$inferSelect
export type UserRow = typeof users.$inferSelect
export type SessionRow = typeof sessions.$inferSelect
export type InviteRow = typeof invites.$inferSelect
export type ConnectionRow = typeof connections.$inferSelect
export type ProductRow = typeof products.$inferSelect
export type ProductGatewayRow = typeof productGateways.$inferSelect
export type TransactionRowDb = typeof transactions.$inferSelect
export type WebhookEventRow = typeof webhookEvents.$inferSelect
export type WebhookDeliveryRow = typeof webhookDeliveries.$inferSelect
export type AuditRow = typeof auditLog.$inferSelect
export type NotificationRow = typeof notifications.$inferSelect
export type JobRow = typeof jobs.$inferSelect

/**
 * Enterprise licence keys installed on this (self-hosted) install. The newest one that wasn't removed
 * applies. Only the paid build reads and writes it; the table lives here so there is one migration history.
 */
export const licences = pgTable("licences", {
  id: text("id").primaryKey(),
  /** The licence's own ID, from inside the signed key. */
  licenceId: text("licence_id").notNull(),
  key: text("key").notNull(),
  customer: text("customer").notNull(),
  expiresAt: ts("expires_at").notNull(),
  installedBy: text("installed_by").references(() => users.id, { onDelete: "set null" }),
  installedAt: ts("installed_at").notNull().defaultNow(),
  removedAt: ts("removed_at"),
})

/** Cloud plans. Prices live in `billing_prices`, one row per change, so past months keep their price. */
export const billingPlans = pgTable(
  "billing_plans",
  {
    id: text("id").primaryKey(),
    slug: text("slug").notNull(),
    name: text("name").notNull(),
    description: text("description").notNull().default(""),
    public: boolean("public").notNull().default(false),
    trialDays: integer("trial_days").notNull().default(14),
    /** Paid features (core FEATURES ids) the plan unlocks. */
    features: text("features").array().notNull().default(sql`'{}'::text[]`),
    active: boolean("active").notNull().default(true),
    createdAt: createdAt(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [uniqueIndex("billing_plans_slug_key").on(t.slug)],
)

/** A plan's price from `effective_from` on (always the start of a UTC month, or 1970 for the first). */
export const billingPrices = pgTable(
  "billing_prices",
  {
    id: text("id").primaryKey(),
    planId: text("plan_id")
      .notNull()
      .references(() => billingPlans.id, { onDelete: "cascade" }),
    effectiveFrom: ts("effective_from").notNull(),
    /** PriceSchedule from @yaropay/core/billing. */
    schedule: jsonb("schedule").$type<Record<string, unknown>>().notNull(),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("billing_prices_plan_idx").on(t.planId, t.effectiveFrom)],
)

/** Naira per one unit of each other currency, kept by the super admin. */
export const exchangeRates = pgTable("exchange_rates", {
  currency: text("currency").primaryKey(),
  nairaPerUnit: text("naira_per_unit").notNull(),
  updatedBy: text("updated_by").references(() => users.id, { onDelete: "set null" }),
  updatedAt: ts("updated_at").notNull().defaultNow(),
})

/** Everything the super admin does. Append-only: the app never updates or deletes these rows. */
export const platformAuditLog = pgTable(
  "platform_audit_log",
  {
    id: text("id").primaryKey(),
    actorId: text("actor_id").references(() => users.id, { onDelete: "set null" }),
    actorEmail: text("actor_email").notNull(),
    action: text("action").notNull(),
    /** "workspace", "plan", "exchange_rates"... */
    targetType: text("target_type").notNull(),
    targetId: text("target_id"),
    /** The workspace it concerns, if any (kept as text so the record outlives the workspace). */
    workspaceId: text("workspace_id"),
    detail: jsonb("detail").$type<Record<string, unknown>>().notNull().default({}),
    ip: text("ip"),
    at: ts("at").notNull().defaultNow(),
  },
  (t) => [index("platform_audit_log_at_idx").on(t.at), index("platform_audit_log_workspace_idx").on(t.workspaceId, t.at)],
)

export type BillingPlanRow = typeof billingPlans.$inferSelect
export type BillingPriceRow = typeof billingPrices.$inferSelect
export type PlatformAuditRow = typeof platformAuditLog.$inferSelect

/** Invoice numbers run across the whole platform: YP-202611-00042. */
export const invoiceNumberSeq = pgSequence("invoice_number_seq", { startWith: 1 })

/**
 * A Cloud company's bill for one UTC month, written once at the start of the next month. Lines and usage
 * are snapshots, so renaming a product or changing a price later never changes a bill already sent.
 */
export const invoices = pgTable(
  "invoices",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    number: text("number").notNull(),
    /** "2026-11" */
    period: text("period").notNull(),
    periodStart: ts("period_start").notNull(),
    periodEnd: ts("period_end").notNull(),
    currency: text("currency").notNull(),
    planSlug: text("plan_slug").notNull(),
    planName: text("plan_name").notNull(),
    /** ChargeLine[] from @yaropay/core/billing. */
    lines: jsonb("lines").$type<Record<string, unknown>[]>().notNull(),
    /** The Usage the lines were priced from (billable part of the month). */
    usage: jsonb("usage").$type<Record<string, unknown>>().notNull(),
    total: bigint("total", { mode: "number" }).notNull(),
    /** `open` (to be paid), `paid`, or `void` (cancelled by the super admin). */
    status: text("status").notNull().default("open"),
    issuedAt: ts("issued_at").notNull().defaultNow(),
    dueAt: ts("due_at").notNull(),
    paidAt: ts("paid_at"),
    /** `card` (charged automatically) or `manual` (marked paid by the super admin, e.g. a bank transfer). */
    paidVia: text("paid_via"),
    note: text("note"),
    /** Automatic charges to the saved card so far, and the last one's outcome. */
    attempts: integer("attempts").notNull().default(0),
    lastAttemptAt: ts("last_attempt_at"),
    lastError: text("last_error"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("invoices_number_key").on(t.number),
    uniqueIndex("invoices_period_key").on(t.workspaceId, t.period),
    index("invoices_status_idx").on(t.status, t.dueAt),
  ],
)

export type InvoiceRow = typeof invoices.$inferSelect

/** A Cloud company's saved card (a reusable Paystack authorization), for charging invoices. */
export const billingPaymentMethods = pgTable("billing_payment_methods", {
  workspaceId: text("workspace_id")
    .primaryKey()
    .references(() => workspaces.id, { onDelete: "cascade" }),
  /** Encrypted Paystack authorization_code. */
  authorizationEnc: text("authorization_enc").notNull(),
  /** The email Paystack knows the customer by (charges must use the same one). */
  email: text("email").notNull(),
  brand: text("brand").notNull().default(""),
  last4: text("last4").notNull().default(""),
  expMonth: text("exp_month").notNull().default(""),
  expYear: text("exp_year").notNull().default(""),
  bank: text("bank").notNull().default(""),
  currency: text("currency").notNull(),
  addedBy: text("added_by").references(() => users.id, { onDelete: "set null" }),
  createdAt: createdAt(),
})

/**
 * Every attempt to take money for YaroPay Cloud: paying an invoice at checkout, charging the saved card,
 * or the small refunded charge that saves a card. The reference makes each one idempotent.
 */
export const billingCharges = pgTable(
  "billing_charges",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    invoiceId: text("invoice_id").references(() => invoices.id, { onDelete: "set null" }),
    reference: text("reference").notNull(),
    /** `invoice_checkout`, `invoice_auto` or `card_check`. */
    purpose: text("purpose").notNull(),
    amount: bigint("amount", { mode: "number" }).notNull(),
    currency: text("currency").notNull(),
    /** `pending`, `success` or `failed`. */
    status: text("status").notNull().default("pending"),
    message: text("message"),
    startedBy: text("started_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    finishedAt: ts("finished_at"),
  },
  (t) => [uniqueIndex("billing_charges_reference_key").on(t.reference), index("billing_charges_invoice_idx").on(t.invoiceId)],
)

export type BillingChargeRow = typeof billingCharges.$inferSelect

// ---- AI apps (MCP) -----------------------------------------------------------------------------------
// Paid feature `mcp`. The tables live here like every other paid table, so there is one migration history.

/** What a company lets AI apps do (Settings → AI apps). No row means the defaults below. */
export const mcpSettings = pgTable("mcp_settings", {
  workspaceId: workspaceId().primaryKey(),
  enabled: boolean("enabled").notNull().default(true),
  allowedRoles: text("allowed_roles").array().notNull().default(sql`ARRAY['owner','admin','developer','finance','viewer']::text[]`),
  liveAllowed: boolean("live_allowed").notNull().default(false),
  actionsAllowed: boolean("actions_allowed").notNull().default(true),
  /** Off: customer emails are masked and names cut to initials in what AI apps receive. */
  shareCustomerDetails: boolean("share_customer_details").notNull().default(false),
  updatedAt: ts("updated_at").notNull().defaultNow(),
  updatedById: text("updated_by_id").references(() => users.id, { onDelete: "set null" }),
})

/**
 * One AI app a member connected (an OAuth sign-in) or one personal access token they created. Tokens
 * hang off it, so revoking the connection ends every token at once.
 */
export const mcpConnections = pgTable(
  "mcp_connections",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    /** `oauth` or `token`. */
    kind: text("kind").notNull(),
    /** The OAuth client; null for personal tokens. */
    clientId: text("client_id"),
    /** The app's name when it connected, or the token's label. */
    name: text("name").notNull(),
    /** `mcp:read`, and `mcp:actions` when actions were allowed. */
    scopes: text("scopes").array().notNull(),
    liveAllowed: boolean("live_allowed").notNull().default(false),
    liveAllowedAt: ts("live_allowed_at"),
    /** Reserved for narrowing products when connecting; null means the member's own products. */
    productIds: text("product_ids").array(),
    /** The MCP server URL the tokens are for (RFC 8707). */
    resource: text("resource").notNull(),
    /** `ypmcp_pat_••••abcd` for personal tokens. */
    tokenPreview: text("token_preview"),
    createdAt: createdAt(),
    expiresAt: ts("expires_at"),
    lastUsedAt: ts("last_used_at"),
    lastUsedIp: text("last_used_ip"),
    revokedAt: ts("revoked_at"),
    revokedById: text("revoked_by_id").references(() => users.id, { onDelete: "set null" }),
    revokeReason: text("revoke_reason"),
  },
  (t) => [uniqueIndex("mcp_connections_workspace_id_key").on(t.workspaceId, t.id), index("mcp_connections_user_idx").on(t.userId)],
)

/** Access, refresh and personal tokens, stored as sha256 hashes like sessions and API keys. */
export const mcpTokens = pgTable(
  "mcp_tokens",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    connectionId: text("connection_id").notNull(),
    /** `access`, `refresh` or `personal`. */
    kind: text("kind").notNull(),
    tokenHash: text("token_hash").notNull(),
    /** Refresh tokens: every rotation of one sign-in shares a family, so a stolen one ends them all. */
    familyId: text("family_id"),
    parentId: text("parent_id"),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    usedAt: ts("used_at"),
    revokedAt: ts("revoked_at"),
  },
  (t) => [
    uniqueIndex("mcp_tokens_token_hash_key").on(t.tokenHash),
    index("mcp_tokens_connection_idx").on(t.connectionId),
    // The database refuses to hang one company's token off another company's connection.
    foreignKey({ name: "mcp_tokens_connection_fk", columns: [t.workspaceId, t.connectionId], foreignColumns: [mcpConnections.workspaceId, mcpConnections.id] }).onDelete("cascade"),
  ],
)

/** Every tool call an AI app made, kept 90 days (Settings → AI apps → Activity). IDs only, no customer data. */
export const mcpToolCalls = pgTable(
  "mcp_tool_calls",
  {
    id: text("id").primaryKey(),
    workspaceId: workspaceId(),
    connectionId: text("connection_id"),
    userId: text("user_id").references(() => users.id, { onDelete: "set null" }),
    clientName: text("client_name").notNull(),
    tool: text("tool").notNull(),
    mode: text("mode"),
    /** `ok`, `error`, `denied`, `approval_required` or `rate_limited`. */
    outcome: text("outcome").notNull(),
    errorCode: text("error_code"),
    approvalId: text("approval_id"),
    durationMs: integer("duration_ms").notNull().default(0),
    ip: text("ip"),
    at: ts("at").notNull().defaultNow(),
  },
  (t) => [index("mcp_tool_calls_workspace_at_idx").on(t.workspaceId, t.at), index("mcp_tool_calls_connection_at_idx").on(t.connectionId, t.at)],
)

export type McpConnectionRow = typeof mcpConnections.$inferSelect
export type McpTokenRow = typeof mcpTokens.$inferSelect
export type McpSettingsRow = typeof mcpSettings.$inferSelect

// ---- AI app sign-in (OAuth 2.1 for MCP) ------------------------------------------------------------------

/**
 * AI apps that may ask members to connect, install-wide (a client isn't any one company's). Either a
 * client ID metadata document (`client_id` is its https URL, fetched and cached) or registered through
 * dynamic client registration (`client_id` is `ocl_…`). Only public clients: no secrets.
 */
export const oauthClients = pgTable(
  "oauth_clients",
  {
    id: text("id").primaryKey(),
    clientId: text("client_id").notNull(),
    /** `cimd` or `dcr`. */
    kind: text("kind").notNull(),
    name: text("name").notNull(),
    clientUri: text("client_uri"),
    logoUri: text("logo_uri"),
    redirectUris: text("redirect_uris").array().notNull(),
    /** The whole document or registration, as received. */
    metadata: jsonb("metadata").notNull().default({}),
    registeredIp: text("registered_ip"),
    createdAt: createdAt(),
    /** CIMD: when the cached document must be fetched again. */
    cacheExpiresAt: ts("cache_expires_at"),
    lastUsedAt: ts("last_used_at"),
    blockedAt: ts("blocked_at"),
  },
  (t) => [uniqueIndex("oauth_clients_client_id_key").on(t.clientId)],
)

/** A sign-in started by an AI app, waiting for the member to pick a company and approve. 10 minutes. */
export const oauthAuthorizationRequests = pgTable("oauth_authorization_requests", {
  id: text("id").primaryKey(),
  clientId: text("client_id").notNull(),
  redirectUri: text("redirect_uri").notNull(),
  state: text("state"),
  codeChallenge: text("code_challenge").notNull(),
  scopes: text("scopes").array().notNull(),
  resource: text("resource").notNull(),
  createdAt: createdAt(),
  expiresAt: ts("expires_at").notNull(),
  consumedAt: ts("consumed_at"),
})

/** One-time authorization codes, 60 seconds, stored as hashes. */
export const oauthCodes = pgTable(
  "oauth_codes",
  {
    codeHash: text("code_hash").primaryKey(),
    workspaceId: workspaceId(),
    connectionId: text("connection_id").notNull(),
    clientId: text("client_id").notNull(),
    redirectUri: text("redirect_uri").notNull(),
    codeChallenge: text("code_challenge").notNull(),
    resource: text("resource").notNull(),
    createdAt: createdAt(),
    expiresAt: ts("expires_at").notNull(),
    usedAt: ts("used_at"),
  },
  (t) => [
    foreignKey({ name: "oauth_codes_connection_fk", columns: [t.workspaceId, t.connectionId], foreignColumns: [mcpConnections.workspaceId, mcpConnections.id] }).onDelete("cascade"),
  ],
)

export type OauthClientRow = typeof oauthClients.$inferSelect
export type OauthAuthorizationRequestRow = typeof oauthAuthorizationRequests.$inferSelect
